<template><section class="panel"><h2>分组数值图</h2><div class="chart" ref="chart" role="img" :aria-label="'演示图表，共 '+rows.length+' 条数据'"></div><p class="note">图表使用上方筛选后的模拟数据；表格保留可阅读明细。</p></section></template><script>export default {props:{rows:{type:Array,required:true}},mounted(){this.instance=window.echarts.init(this.$refs.chart);this.update();this.resize=()=>this.instance?.resize();if(window.ResizeObserver){this.observer=new ResizeObserver(this.resize);this.observer.observe(this.$refs.chart)}else window.addEventListener('resize',this.resize)},watch:{rows:{handler(){this.update()},deep:true}},beforeUnmount(){this.observer?.disconnect();window.removeEventListener('resize',this.resize);this.instance?.dispose()},methods:{update(){if(!this.instance)return;const groups=['A组','B组','C组'];this.instance.setOption({animation:false,tooltip:{trigger:'axis'},xAxis:{type:'category',data:groups},yAxis:{type:'value'},series:[{type:'bar',data:groups.map(group=>this.rows.filter(row=>row.group===group).reduce((sum,row)=>sum+row.value,0)),itemStyle:{color:'#126a60'}}]})}}}</script>
